

-- 1. CREAR ESQUEMA

CREATE SCHEMA IF NOT EXISTS "BillsSchema";

-- 2. TABLA USERS

CREATE TABLE "BillsSchema"."Users" (
    "UserID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" VARCHAR(100) NOT NULL,
    "Email" VARCHAR(150) NOT NULL UNIQUE
);

-- 3. TABLA PRODUCTS

CREATE TABLE "BillsSchema"."Products" (
    "ProductID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" VARCHAR(100) NOT NULL,
    "Price" DOUBLE PRECISION NOT NULL,
    "Stock" INTEGER NOT NULL,
    CONSTRAINT chk_price CHECK ("Price" >= 0),
    CONSTRAINT chk_stock CHECK ("Stock" >= 0)
);

-- 4. TABLA BILLS

CREATE TABLE "BillsSchema"."Bills" (
    "BillID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserID" INTEGER NOT NULL,
    "Date" DATE NOT NULL DEFAULT CURRENT_DATE,
    "Total" DOUBLE PRECISION NOT NULL,
    "Status" VARCHAR(20) NOT NULL DEFAULT 'Activa',

    CONSTRAINT fk_bill_user
        FOREIGN KEY ("UserID")
        REFERENCES "BillsSchema"."Users"("UserID")
);

-- 5. TABLA BILLDETAILS

CREATE TABLE "BillsSchema"."BillDetails" (
    "DetailID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BillID" INTEGER NOT NULL,
    "ProductID" INTEGER NOT NULL,
    "Quantity" INTEGER NOT NULL,
    "UnitPrice" DOUBLE PRECISION NOT NULL,

    CONSTRAINT fk_detail_bill
        FOREIGN KEY ("BillID")
        REFERENCES "BillsSchema"."Bills"("BillID"),

    CONSTRAINT fk_detail_product
        FOREIGN KEY ("ProductID")
        REFERENCES "BillsSchema"."Products"("ProductID"),

    CONSTRAINT chk_quantity CHECK ("Quantity" > 0)
);

